func baseNames(files []string) []string {
	out := make([]string, 0, len(files))
	for _, f := range files {
		out = append(out, strings.TrimRight(f, ".json"))
	}
	return out
}

baseNames([]string{"photo.json", "data.json", "notes.json", "report.json"})

func normalize(body []byte, parts []string) []byte {
	s := strings.TrimSpace(string(body))
	out := ""
	for _, p := range parts {
		out += p + "\n"
	}
	return []byte(s + out)
}
